changeSet.sql:
DO $$
BEGIN
    IF (
        (SELECT count(*) FROM modeling_plan_review) +
        (SELECT count(*) FROM modeling_plan_version)
    ) <> 0 THEN
        RAISE EXCEPTION 'MODELING_PLAN_VERSION_REVIEW_RETIREMENT_LOCKED_RECHECK_FAILED';
    END IF;
END $$;

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODELING_PLAN_VERSION_REVIEW_RETIREMENT_FORWARD_ONLY: recovery requires a new forward changeset';
END $$;
